package remframework.geometry.discovery;
import org.joml.Vector3d;
import java.util.*;
/** Area-objective experiment; it imposes no angle or symmetry target. */
public final class GeometryAreaOptimizer {
    public GeometryOptimizationResult maximize2d(GeometryConfiguration graph,GeometryRealization baseline,ClosedBoundaryResult boundary,double target,int iterations){if(!boundary.closed()||baseline.dimension()!=GeometryEmbeddingDimension.TWO_D)return GeometryOptimizationResult.notAttempted();List<Vector3d> p=baseline.finalCoordinates().stream().map(Vector3d::new).toList();List<Integer> order=boundary.orientedFaces().get(0).nodeIds();double base=area(order,p);double penalty=100;for(int iteration=0;iteration<iterations;iteration++){double step=.01/Math.sqrt(iteration+1);for(int id=2;id<p.size();id++)for(int axis=0;axis<2;axis++){double h=1e-6;Vector3d point=p.get(id);double old=axis==0?point.x:point.y;if(axis==0)point.x=old+h;else point.y=old+h;double plus=objective(graph,order,p,target,penalty);if(axis==0)point.x=old-h;else point.y=old-h;double minus=objective(graph,order,p,target,penalty);if(axis==0)point.x=old;else point.y=old;double gradient=(plus-minus)/(2*h);double update=Math.max(-.02,Math.min(.02,step*gradient));if(axis==0)point.x+=update;else point.y+=update;}}double optimizedArea=area(order,p);boolean preserved=graph.edges().stream().allMatch(e->Math.abs(p.get(e.firstNodeId()).distance(p.get(e.secondNodeId()))-target)<=.02*target);var d=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.OPTIMIZATION,GeometryConfigurationStatusCode.VALID_CANDIDATE,"Area optimization measured","Area was maximized without an angle or symmetry constraint; edge lengths remain a penalty constraint.");GeometryRealization optimized=new GeometryRealization(baseline.seed(),baseline.dimension(),baseline.initialCoordinates(),p,baseline.meanEdgeAccuracy(),0,true,baseline.collisionFree(),baseline.edgeIntersectionFree(),2,GeometryRealizationStatus.REALIZED,List.of(d));GeometricSymmetryResult symmetry=new GeometricSymmetryAnalyzer().analyze(graph,optimized);return new GeometryOptimizationResult(true,baseline,optimized,base,optimizedArea,(optimizedArea-base)/Math.max(base,1e-12),preserved,GeometrySymmetryPolicy.NO_REQUIREMENT,symmetry.geometricallySymmetric(),"Area objective only; symmetry was unconstrained and measured afterward.");}
    private double objective(GeometryConfiguration g,List<Integer> order,List<Vector3d> p,double target,double penalty){double error=0;for(DiscoveryConnection e:g.edges()){double d=p.get(e.firstNodeId()).distance(p.get(e.secondNodeId()))-target;error+=d*d;}return area(order,p)-penalty*error;}
    private double area(List<Integer> ids,List<Vector3d> p){double value=0;for(int i=0;i<ids.size();i++){Vector3d a=p.get(ids.get(i)),b=p.get(ids.get((i+1)%ids.size()));value+=a.x*b.y-b.x*a.y;}return Math.abs(value)/2;}
}
